// Des: Unit tests for cron parse, match and next minute
// Flo: parse cron > match fixed Local > assert fire or reject
// I/O: cron strings + Local > bool, next stamp, error
// ===================================================================
const std = @import("std"); const time = @import("tk-task-time.zig");
const tszz = std.testing; const Local = time.Local; const CronError = time.CronError; const PulseError = time.PulseError; const OnceError = time.OnceError; const SolarError = time.SolarError; const SolarEvent = time.SolarEvent; const ONCE_LATE_WINDOW_MIN = time.ONCE_LATE_WINDOW_MIN;
const daysFromCivil = time.daysFromCivil; const civiDays = time.civiDays; const localFromMinuteStamp = time.localFromMinuteStamp; const yearLeap = time.yearLeap; const montDays = time.montDays; const parseCron = time.parseCron; const cronMatch = time.cronMatch; const nextCronMinute = time.nextCronMinute; const parsePulse = time.parsePulse; const parseOnce = time.parseOnce; const onceDue = time.onceDue; const parseSolar = time.parseSolar; const sunzTime = time.sunzTime;
test "parseCron accepts the standard forms" { _ = try parseCron("0 2 * * *"); _ = try parseCron("*/15 * * * *"); _ = try parseCron("0 9-17 * * 1-5"); _ = try parseCron("0,30 * * * *"); _ = try parseCron("0 0 1 1 *"); _ = try parseCron("59 23 31 12 7"); _ = try parseCron("  0   2   *   *   *  "); }
test "parseCron REJECTS what the hub would silently ignore" { try tszz.expectError(CronError.WrongFieldCount, parseCron("0 2 * *")); try tszz.expectError(CronError.WrongFieldCount, parseCron("0 2 * * * *")); try tszz.expectError(CronError.BadField, parseCron("abc * * * *")); try tszz.expectError(CronError.OutOfRange, parseCron("99 * * * *")); try tszz.expectError(CronError.OutOfRange, parseCron("* 25 * * *")); try tszz.expectError(CronError.OutOfRange, parseCron("* * 32 * *")); try tszz.expectError(CronError.OutOfRange, parseCron("* * * 13 *")); try tszz.expectError(CronError.OutOfRange, parseCron("* * * * 8")); try tszz.expectError(CronError.OutOfRange, parseCron("* * 0 * *")); try tszz.expectError(CronError.BadStep, parseCron("*/0 * * * *")); try tszz.expectError(CronError.BadStep, parseCron("*/x * * * *")); try tszz.expectError(CronError.BadRange, parseCron("10-5 * * * *")); try tszz.expectError(CronError.WrongFieldCount, parseCron("")); try tszz.expectError(CronError.WrongFieldCount, parseCron("   ")); try tszz.expectError(CronError.BadField, parseCron("0,, * * * *")); }
test "cronMatch hits the exact minute and nothing else" { const fiel = try parseCron("30 14 * * *"); const hitz = Local{ .year = 2026, .month = 8, .day = 17, .hour = 14, .minute = 30, .second = 0, .weekday = 1, .minute_stamp = daysFromCivil(2026, 8, 17) * 1440 + 14 * 60 + 30 }; try tszz.expect(cronMatch(fiel, hitz)); var miss = hitz; miss.minute = 31; try tszz.expect(!cronMatch(fiel, miss)); miss = hitz; miss.hour = 15; try tszz.expect(!cronMatch(fiel, miss)); }
test "cronMatch step and range fields" { const ever = try parseCron("*/15 * * * *"); for ([_]u8{ 0, 15, 30, 45 }) |minu| { const loca = Local{ .year = 2026, .month = 8, .day = 17, .hour = 3, .minute = minu, .second = 0, .weekday = 1, .minute_stamp = 0 }; try tszz.expect(cronMatch(ever, loca)); } for ([_]u8{ 1, 14, 16, 44, 59 }) |minu| { const loca = Local{ .year = 2026, .month = 8, .day = 17, .hour = 3, .minute = minu, .second = 0, .weekday = 1, .minute_stamp = 0 }; try tszz.expect(!cronMatch(ever, loca)); } const work = try parseCron("0 9-17 * * 1-5"); const mon1 = Local{ .year = 2026, .month = 8, .day = 17, .hour = 10, .minute = 0, .second = 0, .weekday = 1, .minute_stamp = 0 }; try tszz.expect(cronMatch(work, mon1)); var sat1 = mon1; sat1.weekday = 6; try tszz.expect(!cronMatch(work, sat1)); var mon8 = mon1; mon8.hour = 8; try tszz.expect(!cronMatch(work, mon8)); }
test "dom and dow are OR'd when both restricted — the classic cron bug" { const fiel = try parseCron("0 0 1 * 1"); const firs = Local{ .year = 2026, .month = 7, .day = 1, .hour = 0, .minute = 0, .second = 0, .weekday = 3, .minute_stamp = 0 }; try tszz.expect(cronMatch(fiel, firs)); const mond = Local{ .year = 2026, .month = 8, .day = 17, .hour = 0, .minute = 0, .second = 0, .weekday = 1, .minute_stamp = 0 }; try tszz.expect(cronMatch(fiel, mond)); const tues = Local{ .year = 2026, .month = 8, .day = 18, .hour = 0, .minute = 0, .second = 0, .weekday = 2, .minute_stamp = 0 }; try tszz.expect(!cronMatch(fiel, tues)); }
test "dow 7 and 0 are both Sunday" { const fie7 = try parseCron("0 0 * * 7"); const fie0 = try parseCron("0 0 * * 0"); const sund = Local{ .year = 2026, .month = 8, .day = 16, .hour = 0, .minute = 0, .second = 0, .weekday = 0, .minute_stamp = 0 }; try tszz.expect(cronMatch(fie7, sund)); try tszz.expect(cronMatch(fie0, sund)); }
test "nextCronMinute finds the following occurrence" { const fiel = try parseCron("0 2 * * *"); const nowz = localFromMinuteStamp(daysFromCivil(2026, 8, 17) * 1440 + 3 * 60); const next = nextCronMinute(fiel, nowz).?; const nloc = localFromMinuteStamp(next); try tszz.expectEqual(@as(u8, 2), nloc.hour); try tszz.expectEqual(@as(u8, 0), nloc.minute); try tszz.expectEqual(@as(u8, 18), nloc.day); try tszz.expect(next > nowz.minute_stamp); }
test "nextCronMinute handles a Feb 29 only schedule" { const fiel = try parseCron("0 0 29 2 *"); const nowz = localFromMinuteStamp(daysFromCivil(2026, 3, 1) * 1440); const next = nextCronMinute(fiel, nowz).?; const nloc = localFromMinuteStamp(next); try tszz.expectEqual(@as(u16, 2028), nloc.year); try tszz.expectEqual(@as(u8, 2), nloc.month); try tszz.expectEqual(@as(u8, 29), nloc.day); }
test "hour [groups]: valid and invalid forms" { _ = try parseCron("08 [09,10,11],[15,16],[22] * * *"); _ = try parseCron("0 07,[13,14],19 * * *"); _ = try parseCron("0 [9-11] * * *"); try tszz.expectError(CronError.BadField, parseCron("0 [09,10 * * *")); try tszz.expectError(CronError.BadField, parseCron("0 [] * * *")); try tszz.expectError(CronError.BadField, parseCron("0 [*] * * *")); try tszz.expectError(CronError.BadField, parseCron("0 [[9]] * * *")); try tszz.expectError(CronError.BadField, parseCron("0 9 [5] * *")); try tszz.expectError(CronError.OutOfRange, parseCron("0 [9,25] * * *")); }
test "hour [groups]: a..b ranges pick inside their window, one per group" { const best = try parseCron("8 [09..11],[15..17],[21..23] * * *"); var dayz: i64 = 1; while (dayz <= 20) : (dayz += 1) { var inwi = [3]u8{ 0, 0, 0 }; var hour: i64 = 0; while (hour < 24) : (hour += 1) { if (!cronMatch(best, localFromMinuteStamp(daysFromCivil(2026, 3, @intCast(dayz)) * 1440 + hour * 60 + 8))) continue; if (hour >= 9 and hour <= 11) inwi[0] += 1 else if (hour >= 15 and hour <= 17) inwi[1] += 1 else if (hour >= 21 and hour <= 23) inwi[2] += 1 else return error.PickOutsideWindow; } try tszz.expectEqual([3]u8{ 1, 1, 1 }, inwi); } _ = try parseCron("0 [9..11],[15] * * *"); try tszz.expectError(CronError.BadField, parseCron("0 [11..9] * * *")); try tszz.expectError(CronError.BadField, parseCron("0 [9..] * * *")); try tszz.expectError(CronError.OutOfRange, parseCron("0 [9..25] * * *")); }
test "hour [groups]: one hour per group per day, stable, varies by day" { const fiel = try parseCron("8 [9,10,11],[15,16],[22] * * *"); var diff = false; var prev: i64 = -1; var dayz: u8 = 1; while (dayz <= 28) : (dayz += 1) { var hits: u32 = 0; var ingr: i64 = -1; var hour: u8 = 0; while (hour < 24) : (hour += 1) { const loca = localFromMinuteStamp(daysFromCivil(2026, 3, dayz) * 1440 + @as(i64, hour) * 60 + 8); if (cronMatch(fiel, loca)) { hits += 1; if (hour <= 11) ingr = hour; } } try tszz.expectEqual(@as(u32, 3), hits); try tszz.expect(ingr >= 9 and ingr <= 11); if (prev >= 0 and prev != ingr) diff = true; prev = ingr; } try tszz.expect(diff); }
test "minute [groups]: one random minute per firing hour, stable, differs across triggers" { const fiel = try parseCron("[00..59] [09,10,11],[15,16,17],[21,22,23] * * *"); _ = try parseCron("[0,30] 9 * * *"); try tszz.expectError(CronError.OutOfRange, parseCron("[0..60] 9 * * *")); try tszz.expectError(CronError.BadField, parseCron("[] 9 * * *")); try tszz.expectError(CronError.BadField, parseCron("0 9 [1] * *")); var same = true; var firs: i64 = -1; var dayz: i64 = 1; while (dayz <= 20) : (dayz += 1) { var hits: u32 = 0; var hour: i64 = 0; while (hour < 24) : (hour += 1) { var minu: i64 = 0; while (minu < 60) : (minu += 1) { const loca = localFromMinuteStamp(daysFromCivil(2026, 3, @intCast(dayz)) * 1440 + hour * 60 + minu); if (!cronMatch(fiel, loca)) continue; hits += 1; if (firs < 0) firs = minu else if (firs != minu) same = false; } } try tszz.expectEqual(@as(u32, 3), hits); } try tszz.expect(!same); }
test "hour [groups]: mixed with fixed hours" { const fiel = try parseCron("0 7,[13,14],19 * * *"); const dayz = daysFromCivil(2026, 3, 5) * 1440; try tszz.expect(cronMatch(fiel, localFromMinuteStamp(dayz + 7 * 60))); try tszz.expect(cronMatch(fiel, localFromMinuteStamp(dayz + 19 * 60))); const hit1 = cronMatch(fiel, localFromMinuteStamp(dayz + 13 * 60)); const hit2 = cronMatch(fiel, localFromMinuteStamp(dayz + 14 * 60)); try tszz.expect(hit1 != hit2); }
